                    '.github/workflows/* which the silent token can never create or update — wire an App ' +
                    'installation token with "Workflows: write" or a PAT with the `workflow` scope');
            }
            set_env_variable('GH_TOKEN', escalationToken);
            try {
                return update();
            } catch (eEsc) {
                if (validationLiveness.isWorkflowsPermissionRejection(eEsc && eEsc.message)) {
                    // AC3: the escalation token ALSO lacks workflow write.
