function escalationSm(itemExtra, failPlan, githubExtra, topExtra) {
    var stderrByPath = {};
    var cloneCommands = [];
    var sm = makeSmAgent(Object.assign({
        fileMap: { '../.dmtools/config.js': CONFIG_1106 },
