                }
                if (fail === 'workflows') {
                    throw new Error('Tool execution failed: ' + workflowsStderr());
                }
                if (fail instanceof Error) throw fail;
                return '';
            }
            return '';
        }
    }, topExtra || {}));
    sm.cloneCommands = cloneCommands;
    return sm;
}

