// Istanbul / nyc coverage JSON parsing and per-method attribution.
//
// The Istanbul JSON structure is:
//   { "/abs/path.js": { statementMap: {id: {start:{line,col}, end:{line,col}}},
//                       s: {id: hitCount}, ... } }
